local mios_state = rawget(_G, "MIOS_SESSION") or {}
local function mios_section(name, fn)
 local ok, err = pcall(fn)
 if not ok then
  local m = "MiOS: Hyprland " .. name .. " section failed: " .. tostring(err)
  if io and io.stderr then io.stderr:write(m .. "\n") end
  mios_state.errors = mios_state.errors or {}
  table.insert(mios_state.errors, m)
 end
end
