mios_section("framerate", function()
 local excluded = {"HEADLESS-"}
 local function local_output(name)
  for _, p in ipairs(excluded) do if name:sub(1, #p) == p then return false end end
  return true
 end
 local runtime = os.getenv("XDG_RUNTIME_DIR")
 local f = runtime and io.open(runtime .. "/mios/framerate/state.json", "r")
 local s = ""
 if f then s = f:read("*a") or "" f:close() end
 local pid = s:match('"pid"%s*:%s*(%d+)')
 local c = pid and io.open("/proc/" .. pid .. "/comm", "r")
 local comm = ""
 if c then comm = c:read("*l") or "" c:close() end
 local function n(k) return tonumber(s:match('"' .. k .. '"%s*:%s*(%d+)')) end
 local tier = s:match('"tier"%s*:%s*"([%w%-]+)"')
 if comm == "miosd" and tier and n("desktop_hz") and n("cap_hz") and n("glass_fps") and n("wallpaper_fps") then
  mios_rate = {tier = tier, desktop_hz = n("desktop_hz"), cap_hz = n("cap_hz"), glass_fps = n("glass_fps"), wallpaper_fps = n("wallpaper_fps"), wallpaper_paced = s:match('"wallpaper_paced"%s*:%s*true') ~= nil, source = "state"}
  for name, mode in s:gmatch('"mode%.([%w%-_%.]+)"%s*:%s*"([^"]+)"') do
   local ok = mode:match('^%d+x%d+@[%d%.]+$') or mode:match('^modeline [%d%. ]+ [%+%-]hsync [%+%-]vsync$')
   local m = ok and local_output(name) and hl.get_monitor(name)
   if m then hl.monitor({output = name, mode = mode, position = m.x .. "x" .. m.y, scale = m.scale, transform = m.transform}) end
  end
 elseif mios_rate.cap_hz == 0 then
  local max = 0
  for _, m in ipairs(hl.get_monitors() or {}) do
   if local_output(m.name) then
    for _, mode in ipairs(m.available_modes or {}) do max = math.max(max, math.floor(mode.refresh_rate + 0.5)) end
   end
  end
  mios_rate.desktop_hz = max
  mios_rate.glass_fps = math.floor(max / 2)
  mios_rate.wallpaper_fps = math.floor(max / 1)
 end
 mios_state.framerate = mios_rate
end)
