mios_section("windowshade", function()
hl.plugin.load("/usr/lib64/mios/windowshade.so")
local mios_fx = (os.getenv("XDG_RUNTIME_DIR") or "/tmp") .. "/mios-shader-"
do
 local palette = {["bg"] = "282262", ["fg"] = "E7DFD3", ["accent"] = "1A407F", ["cursor"] = "F35C15", ["success"] = "3E7765", ["warning"] = "F35C15", ["error"] = "DC271B", ["info"] = "1A407F", ["muted"] = "948E8E", ["subtle"] = "B7C9D7", ["earth"] = "734F39", ["silver"] = "E0E0E0", ["ansi_0_black"] = "282262", ["ansi_1_red"] = "DC271B", ["ansi_2_green"] = "3E7765", ["ansi_3_yellow"] = "F35C15", ["ansi_4_blue"] = "1A407F", ["ansi_5_magenta"] = "734F39", ["ansi_6_cyan"] = "B7C9D7", ["ansi_7_white"] = "E7DFD3", ["ansi_8_bright_black"] = "948E8E", ["ansi_9_bright_red"] = "FF6B5C", ["ansi_10_bright_green"] = "5FAA8E", ["ansi_11_bright_yellow"] = "FF8540", ["ansi_12_bright_blue"] = "3D6BA8", ["ansi_13_bright_magenta"] = "9D7660", ["ansi_14_bright_cyan"] = "E0E0E0", ["ansi_15_bright_white"] = "FFFFFF"}
 local src = "/usr/share/mios/hyprland/shaders" .. "/"
 for _, name in ipairs({"glass-dissolve-close", "glass-dissolve-open", "none-close", "none-open"}) do
  local i = io.open(src .. name .. ".glsl", "r")
  if i then
   local s = i:read("a")
   i:close()
   s = s:gsub("vec3%b()(;%s*// @palette ([%w_]+))", function(rest, key)
    local h = palette[key]
    if not h then return nil end
    return string.format("vec3(%.4f, %.4f, %.4f)%s", tonumber(h:sub(1, 2), 16) / 255, tonumber(h:sub(3, 4), 16) / 255, tonumber(h:sub(5, 6), 16) / 255, rest)
   end)
   local o = io.open(mios_fx .. name .. ".glsl", "w")
   if o then o:write(s) o:close() end
  end
 end
end
