mios_section("global-input", function()
 local policies={}
 local escapes={}
 local capture_fullscreen=true
 local capture_tag="mios-input-captured"
 policies["SUPER+space"]={contexts={},passthrough={"vm-passthrough"}}
 escapes["SUPER+space"]="SUPER+CTRL+space"
 policies["SUPER+return"]={contexts={},passthrough={"vm-passthrough"}}
 escapes["SUPER+return"]="SUPER+CTRL+return"
 policies["SUPER+c"]={contexts={},passthrough={"vm-passthrough"}}
 policies["SUPER+v"]={contexts={},passthrough={"vm-passthrough"}}
 policies["SUPER+f11"]={contexts={},passthrough={"vm-passthrough"}}
 escapes["SUPER+f11"]="SUPER+CTRL+f11"
 policies["SUPER+f12"]={contexts={},passthrough={"vm-passthrough"}}
 policies["SUPER+escape"]={contexts={},passthrough={"vm-passthrough"}}
 escapes["SUPER+escape"]="SUPER+CTRL+escape"
 policies["SUPER+CTRL+equal"]={contexts={},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+equal",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd dispatch 'mios:session-scale-up'"))
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+equal"}) end
 policies["SUPER+CTRL+minus"]={contexts={},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+minus",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd dispatch 'mios:session-scale-down'"))
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+minus"}) end
 policies["SUPER+CTRL+0"]={contexts={},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+0",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd dispatch 'mios:session-scale-reset'"))
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+0"}) end
 policies["SUPER+CTRL+mouse_up"]={contexts={},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+mouse_up",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd dispatch 'mios:session-scale-up'"))
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+mouse_up"}) end
 policies["SUPER+CTRL+mouse_down"]={contexts={},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+mouse_down",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd dispatch 'mios:session-scale-down'"))
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+mouse_down"}) end
 policies["SUPER+CTRL+p"]={contexts={"desktop-2d","desktop-3d","vm-passthrough"},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+p",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd vm-action toggle_vm_passthrough"),{dont_inhibit=true,submap_universal=true})
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+p",escape=true}) end
 policies["SUPER+CTRL+f"]={contexts={"vm-passthrough"},passthrough={}}
 local b=mios_native_hl.bind("SUPER+CTRL+f",mios_native_hl.dsp.exec_cmd("/usr/libexec/mios/mios-inputd vm-action vm-fullscreen"),{dont_inhibit=true,submap_universal=true})
 if b then table.insert(mios_input_handles,{handle=b,key="SUPER+CTRL+f",escape=true}) end
 policies["SUPER+CTRL+m"]={contexts={"vm-passthrough"},passthrough={}}
 local lg_classes={"looking-glass-client"}
 local lg_key="Scroll_Lock"
 local held=nil
 local function release_vm_command()
  local h=held; held=nil
  if not h then return end
  for _,w in ipairs(hl.get_windows() or {}) do
   if w.address==h.address and w.pid==h.pid then
    pcall(function() hl.dispatch(hl.dsp.send_key_state({mods='',key=lg_key,state='up',window='address:'..h.address})) end)
   end
  end
 end
 local function press_vm_command()
  if held then return end
  local w=hl.get_active_window(); if not w then return end
  local allowed=false; for _,class in ipairs(lg_classes) do if w.class==class then allowed=true end end
  if not allowed then return end
  held={address=w.address,pid=w.pid}
  hl.dispatch(hl.dsp.send_key_state({mods='',key=lg_key,state='down',window='address:'..w.address}))
 end
 hl.on('window.active',release_vm_command)
 hl.on('config.reloaded',release_vm_command)
 local down=mios_native_hl.bind("SUPER+CTRL+m",press_vm_command,{dont_inhibit=true,submap_universal=true})
 local up=mios_native_hl.bind("SUPER+CTRL+m",release_vm_command,{release=true,dont_inhibit=true,submap_universal=true})
 if down then table.insert(mios_input_handles,{handle=down,key="SUPER+CTRL+m",escape=true}) end
 hl.window_rule({name="mios-input-vm-passthrough",match={class="^(looking-glass-client|xfreerdp|wlfreerdp|sdl-freerdp|winapps|virt-manager|remote-viewer|qemu-system-x86_64)$"},tag="+mios-input-vm-passthrough"})
 hl.window_rule({name="mios-input-game",match={class="^(steam_app_.*|gamescope|Waydroid)$"},tag="+mios-input-game"})
 hl.window_rule({name="mios-input-terminal",match={class="^(mios-terminal|Alacritty|kitty|foot)$"},tag="+mios-input-terminal"})
 local function canonical(key)
  key=key:gsub('%s','')
  local mods,leaf={},nil
  for token in key:gmatch('[^+]+') do
   local u=token:upper()
   if u=='SUPER' or u=='CTRL' or u=='ALT' or u=='SHIFT' then mods[u]=true else leaf=token:lower() end
  end
  local parts={}
  for _,m in ipairs({'SUPER','CTRL','ALT','SHIFT'}) do if mods[m] then table.insert(parts,m) end end
  table.insert(parts,leaf or '')
  return table.concat(parts,'+')
 end
 local function contains(list,value) for _,v in pairs(list or {}) do if type(v)=='string' and v:gsub('%*$','')==value then return true end end return false end
 local function context()
  local w=hl.get_active_window()
  local tags=w and w.tags or {}
  if (w and capture_fullscreen and tonumber(w.fullscreen)==2) or contains(tags,capture_tag) then return 'app-capture' end
  local ok,room=pcall(function() return hl.plugin.hypr3d.active() end)
  if ok and room then return 'desktop-3d' end
  if contains(tags,'mios-input-vm-passthrough') then return 'vm-passthrough' end
  if contains(tags,'mios-input-game') then return 'game' end
  if contains(tags,'mios-input-terminal') then return 'terminal' end
  return 'desktop-2d'
 end
 local function refresh()
  local ctx=context()
  for _,v in ipairs(mios_input_handles) do
   local p=policies[canonical(v.key)]
   local enabled=ctx~='vm-passthrough'
   if p then enabled=(#p.contexts==0 or contains(p.contexts,ctx)) and not contains(p.passthrough,ctx) end
   if ctx=='app-capture' or ctx=='vm-passthrough' then enabled=v.escape==true end
   v.handle:set_enabled(enabled)
  end
 end
 local extra={}
 for _,v in ipairs(mios_input_handles) do
  local escape=escapes[canonical(v.key)]
  if escape then
   local b=mios_native_hl.bind(escape,v.dispatcher,{dont_inhibit=true,submap_universal=true})
   if b then table.insert(extra,{handle=b,key=escape,escape=true}) end
  end
 end
 for _,v in ipairs(extra) do table.insert(mios_input_handles,v) end
 -- Expose read-only status for native integration tests and the global map UI.
 MIOS_INPUT_POLICY={handles=mios_input_handles,context=context,refresh=refresh}
 hl.on('window.active',refresh)
 hl.on('window.class',refresh)
 hl.on('window.fullscreen',refresh)
 hl.on('window.update_rules',refresh)
 refresh()
end)
-- MiOS mobile layout profile ([desktop.mobile])
-- Every output (local or remote per applies_to; remote = connector name starts with a
-- remote_name_prefixes entry, the RDP virtual display being a Hyprland headless output) is run
-- through the global scale policy ([desktop.scaling], mios_scale_policy below: density from the
-- client DPI hint / EDID mm / resolution x viewing distance x orientation). Its scale is applied to
-- outputs without an operator-saved scale when apply_to allows (deferred to a one-shot timer, never
-- inside the event), and its mobile flag (logical short side under the breakpoint) selects the
-- phone profile: a per-output workspace rule (one-window layout, no top gap so the window meets the
-- shell's shoulders) and a window rule that tiles new windows there (never a window class whose own rule
-- floats and pins it: the ShaderGlass pane; this rule is made later, so it would win). Mobile windows keep the GLOBAL
-- decoration (rounding, border, shadow, hyprglass) exactly like desktop windows. Their controls:
-- hyprbars_tab = "mobile" puts them on the window's own glass split into two touch tabs (hyprbars:mobile,
-- when the plugin took the mobile keys: mios_state.hyprbars_mobile; otherwise the shell draws them),
-- false hides the hyprbars tab (the shell draws the controls), true keeps the desktop tab. Without
-- [desktop.scaling] the legacy rule applies (portrait, or narrower than breakpoint_px). Rules are
-- made when such an output appears and enabled/disabled as outputs come, go, rotate or rescale
-- (monitor.added/removed/layout_changed); nothing is keyed to an output name except the operator's
-- saved scales (EXPLICIT). Windows on outputs of an origin in remote_effects.applies_to (the RDP
-- display) are tagged with the remote glass preset FX (a copy of the desktop preset with fewer blur
-- passes and no specular/fresnel/chromatic extras: cheaper to render and capture). The verdict is
-- published for Quickshell (Mobile.qml) in $XDG_RUNTIME_DIR/mios-mobile-outputs.json; remote DPI
-- hints are read from $XDG_RUNTIME_DIR/mios-display-hints.json ({"outputs": {"<name>": {"dpi": N}}}).
do
 local ok, err = pcall(function()
  local M = {enabled = true, portrait = true, breakpoint = 900, applies = {["local"] = true, ["remote"] = true},
   prefixes = {"HEADLESS-"}, layout = "monocle", gaps_in = 0, gaps_out = 6,
   hyprbars_tab = "mobile"}
  local config_json = "{\"enabled\":true,\"portrait\":true,\"breakpoint_px\":900,\"applies_to\":[\"local\",\"remote\"],\"remote_name_prefixes\":[\"HEADLESS-\"],\"layout\":\"monocle\",\"gaps_in_px\":0,\"gaps_out_px\":6,\"hyprbars_tab\":\"mobile\",\"notch_gap_px\":6,\"shoulder_dot_px\":14,\"app_menu\":true,\"island_motion\":\"fadeIn\",\"island_hold\":[\"windowsOut\",\"fadeOut\"],\"window_controls\":[{\"label\":\"Close\",\"icon\":\"✕\",\"action\":\"hyprctl dispatch 'hl.dsp.window.close({window = \\\"address:{address}\\\"})'\"},{\"label\":\"Minimize\",\"icon\":\"–\",\"action\":\"hyprctl dispatch '(hl.plugin.mios_lamp and hl.plugin.mios_lamp.minimize({window = \\\"address:{address}\\\"}) or hl.dsp.window.move({workspace = \\\"special:minimized\\\", window = \\\"address:{address}\\\", follow = false}))'\"},{\"label\":\"Float\",\"icon\":\"□\",\"action\":\"hyprctl dispatch 'hl.dsp.window.float({action = \\\"toggle\\\", window = \\\"address:{address}\\\"})'\"}],\"remote_effects\":{\"enabled\":false,\"applies_to\":[\"remote\"],\"preset\":\"mios-remote\",\"base_preset\":\"mios\",\"layer_namespaces\":[\"mios-topbar\",\"mios-dock\"],\"overrides\":{\"blur_iterations\":1,\"specular_strength\":0.0,\"fresnel_strength\":0.0,\"chromatic_aberration\":0.0}}}"
  local S = {enabled = true, apply_local = true, apply_remote = false, target_dpi = 96.0, handheld_dpi = 160.0, handheld_diag = 7.0, desktop_diag = 15.0, min_scale = 1.0, max_scale = 3.0, snap_step = 0.25, min_short = 360, mobile_short = 600, mobile_long = 1400, portrait_mobile = false, min_phys_mm = 50.0, edid_tol = 0.15, fb_desktop_diag = 24.0, fb_handheld_dpi = 400.0, hh_aspect = 1.85, hh_short = 1440}
  -- Global so `mios-gen session-scale` can mark an output it scaled explicit in the live session.
  MIOS_SCALE_EXPLICIT = {}
  local EXPLICIT = MIOS_SCALE_EXPLICIT
  local FX = nil
local function mios_scale_policy(P, m)
 local G = 120
 local function round_i(x) return math.floor(x + 0.5) end
 local w, h = math.max(1, math.floor(tonumber(m.width) or 0)), math.max(1, math.floor(tonumber(m.height) or 0))
 local pw, ph = tonumber(m.pw) or 0, tonumber(m.ph) or 0
 if (tonumber(m.transform) or 0) % 2 == 1 then w, h = h, w; pw, ph = ph, pw end
 local diag_px = math.sqrt(w * w + h * h)
 local short, long = math.min(w, h), math.max(w, h)
 local aspect = long / short
 local diag_mm = math.sqrt(pw * pw + ph * ph)
 local edid_ok = pw > 0 and ph > 0 and diag_mm >= P.min_phys_mm and math.abs((pw / ph) / (w / h) - 1.0) <= P.edid_tol
 local hint = tonumber(m.dpi)
 if hint and not (hint > 0 and hint < math.huge) then hint = nil end
 local handheld_shape = m.remote and short <= P.hh_short and (h > w or aspect >= P.hh_aspect)
 local source, dpi, diag_in
 if hint then source, dpi, diag_in = "dpi-hint", hint, diag_px / hint
 elseif edid_ok then diag_in = diag_mm / 25.4; source, dpi = "edid", diag_px / diag_in
 elseif handheld_shape then source, dpi, diag_in = "fallback-handheld", P.fb_handheld_dpi, diag_px / P.fb_handheld_dpi
 else source, dpi, diag_in = "fallback-desktop", diag_px / P.fb_desktop_diag, P.fb_desktop_diag end
 local target
 if diag_in <= P.handheld_diag then target = P.handheld_dpi
 elseif diag_in >= P.desktop_diag then target = P.target_dpi
 else target = P.handheld_dpi + (P.target_dpi - P.handheld_dpi) * (diag_in - P.handheld_diag) / (P.desktop_diag - P.handheld_diag) end
 local step, kmin, kmax = round_i(P.snap_step * G), round_i(P.min_scale * G), round_i(P.max_scale * G)
 local k = round_i(dpi / target * G / step) * step
 k = math.min(k, kmax)
 if P.min_short > 0 then k = math.min(k, math.floor(short * G / P.min_short)) end
 k = math.max(k, kmin)
 local valid, c = G, k
 while c >= kmin and c >= 1 do
  if (w * G) % c == 0 and (h * G) % c == 0 then valid = c break end
  c = c - 1
 end
 if not P.enabled then valid = G end
 local ex = tonumber(m.explicit)
 if ex and not (ex > 0 and ex < math.huge) then ex = nil end
 local scale, k120
 if ex then
  local ke = math.max(1, round_i(ex * G))
  while ke > 1 and not ((w * G) % ke == 0 and (h * G) % ke == 0) do ke = ke - 1 end
  scale, k120, source = ke / G, ke, "explicit"
 elseif not P.enabled then scale, k120, source = 1.0, G, "disabled"
 else scale, k120 = valid / G, valid end
 local lw, lh = round_i(w / scale), round_i(h / scale)
 local ls, ll = math.min(lw, lh), math.max(lw, lh)
 local mobile = (ls < P.mobile_short and ll < P.mobile_long) or (P.portrait_mobile and lh > lw)
 local auto = P.enabled and not ex and ((m.remote and P.apply_remote) or (not m.remote and P.apply_local))
 return {scale = scale, scale_120 = k120, logical_width = lw, logical_height = lh, mobile = mobile and true or false,
  explicit = ex ~= nil, source = source, dpi = dpi, diagonal_in = diag_in, target_dpi = target, auto_apply = auto and true or false}
end
  local rules, fxrules, applied, timers = {}, {}, {}, {}
  -- The remote glass preset exists only if hyprglass is loaded; without it nothing is tagged.
  if FX then
   local hg = hl.plugin and hl.plugin.hyprglass
   local okp, e = false, "hyprglass not loaded"
   if hg and type(hg.preset) == "function" then okp, e = pcall(hg.preset, FX.preset, FX.spec) end
   if not okp then
    if hg and io and io.stderr then io.stderr:write("MiOS: remote glass preset: " .. tostring(e) .. "\n") end
    FX = nil
   elseif type(hg.layer) == "function" then
    -- shell layers opt in by namespace (<ns>-remote, Mobile.layerNamespace): hyprglass layer presets
    -- are per namespace, not per output
    for _, ns in ipairs(FX.layers) do pcall(hg.layer, ns .. "-remote", {preset = FX.preset}) end
   end
  end
  local bars = hl.plugin ~= nil and hl.plugin.hyprbars ~= nil
  local MS = rawget(_G, "MIOS_SESSION") or {}
  -- the plugin's split touch tabs need the MiOS patch's mobile keys to have been accepted
  local mobiletabs = M.hyprbars_tab == "mobile" and bars and MS.hyprbars_mobile == true
  local nobar = M.hyprbars_tab ~= true and bars
  local tabs_live = false
  local function origin(name)
   for _, p in ipairs(M.prefixes) do
    if name:sub(1, #p) == p then return "remote" end
   end
   return "local"
  end
  local function logical(m)
   local w, h, s = tonumber(m.width) or 0, tonumber(m.height) or 0, tonumber(m.scale) or 1
   if s <= 0 then s = 1 end
   if (tonumber(m.transform) or 0) % 2 == 1 then w, h = h, w end
   return math.floor(w / s + 0.5), math.floor(h / s + 0.5)
  end
  local function is_mobile(name, w, h)
   if not M.enabled or w <= 0 or h <= 0 or not M.applies[origin(name)] then return false end
   return (M.portrait and h > w) or w < M.breakpoint
  end
  local function dpi_hints()
   local hints, dir = {}, os and os.getenv and os.getenv("XDG_RUNTIME_DIR")
   local f = dir and io and io.open and io.open(dir .. "/mios-display-hints.json")
   if not f then return hints end
   local j = f:read("*a") or ""
   f:close()
   local body = j:match('"outputs"%s*:%s*(%b{})') or ""
   for name, o in body:gmatch('"([%w_%-]+)"%s*:%s*(%b{})') do
    local d = tonumber(o:match('"dpi"%s*:%s*([%d%.]+)'))
    if d and d > 0 then hints[name] = d end
   end
   return hints
  end
  -- Policy verdict for one output; the legacy breakpoint rule when [desktop.scaling] is absent.
  local function decide(m, name, lw, lh, hints)
   local cur = tonumber(m.scale) or 1
   if not S then
    return {mobile = is_mobile(name, lw, lh), scale = cur, scale_120 = math.floor(cur * 120 + 0.5),
     logical_width = lw, logical_height = lh, explicit = false, auto_apply = false, source = "legacy", dpi = 0}
   end
   local d = mios_scale_policy(S, {width = m.width, height = m.height, pw = m.physical_width, ph = m.physical_height,
    dpi = hints[name], transform = m.transform, remote = origin(name) == "remote", explicit = EXPLICIT[name]})
   d.mobile = (M.enabled and M.applies[origin(name)] and d.mobile) and true or false
   return d
  end
  -- Apply the policy scale to a non-explicit output: once per (mode, transform, scale), so a scale
  -- Hyprland substitutes can never loop, and from a one-shot timer, never inside the event itself.
  local function schedule(m, name, d)
   local cur = tonumber(m.scale) or 1
   if not d.auto_apply or math.abs(cur * 120 - d.scale_120) < 0.5 then return end
   local key = string.format("%dx%d:%d:%d", tonumber(m.width) or 0, tonumber(m.height) or 0, tonumber(m.transform) or 0, d.scale_120)
   if applied[name] == key or type(hl.timer) ~= "function" or type(hl.monitor) ~= "function" then return end
   applied[name] = key
   local spec = {output = name, scale = d.scale, transform = tonumber(m.transform) or 0,
    mode = string.format("%dx%d@%.3f", tonumber(m.width) or 0, tonumber(m.height) or 0, tonumber(m.refresh_rate) or 60),
    position = string.format("%dx%d", tonumber(m.x) or 0, tonumber(m.y) or 0)}
   timers[name] = hl.timer(function()
    timers[name] = nil
    local oka, e = pcall(hl.monitor, spec)
    if not oka and io and io.stderr then io.stderr:write("MiOS: scale policy: " .. tostring(e) .. "\n") end
   end, {timeout = 1, type = "oneshot"})
  end
  local function apply(name, on)
   local r = rules[name]
   if on and not r then
    local sel = "m[" .. name .. "]"
    -- layout and gaps only: mobile windows inherit the global decoration (rounding, border, glass)
    rules[name] = {
     hl.workspace_rule({workspace = sel, layout = M.layout, gaps_in = M.gaps_in,
      gaps_out = {top = 0, right = M.gaps_out, bottom = M.gaps_out, left = M.gaps_out}}),
     hl.window_rule({name = "mios-mobile-" .. name, match = {workspace = sel, float = false, class = "negative:^(shaderglass\\.exe)$"}, tile = true}),
    }
    local tabbed = false
    if mobiletabs then
     local okt, rt = pcall(hl.window_rule, {name = "mios-mobile-tabs-" .. name, match = {workspace = sel}, ["hyprbars:mobile"] = true})
     if okt and rt then table.insert(rules[name], rt) tabbed = true end
    end
    if tabbed then
     tabs_live = true
    elseif nobar then
     local okb, rb = pcall(hl.window_rule, {name = "mios-mobile-nobar-" .. name, match = {workspace = sel}, ["hyprbars:no_bar"] = true})
     if okb and rb then table.insert(rules[name], rb) end
    end
   elseif r then
    for _, rule in ipairs(r) do pcall(rule.set_enabled, rule, on) end
   end
  end
  -- Remote glass preset on every window of a remote_effects output (dynamic tag: a window moved to
  -- a local output loses it).
  local function apply_fx(name, on)
   if not FX then return end
   local r = fxrules[name]
   if on and not r then
    local okr, rr = pcall(hl.window_rule, {name = "mios-remote-fx-" .. name, match = {workspace = "m[" .. name .. "]"},
     tag = "+hyprglass_preset_" .. FX.preset})
    if okr and rr then fxrules[name] = rr end
   elseif r then
    pcall(r.set_enabled, r, on)
   end
  end
  local function jstr(s)
   return '"' .. (tostring(s):gsub('[%c"\\]', function(c) return string.format("\\u%04x", c:byte()) end)) .. '"'
  end
  local function publish(state)
   local dir = os and os.getenv and os.getenv("XDG_RUNTIME_DIR")
   if not dir or not io or not io.open then return end
   local path = dir .. "/mios-mobile-outputs.json"
   local names, parts = {}, {}
   for name in pairs(state) do names[#names + 1] = name end
   table.sort(names)
   for _, name in ipairs(names) do
    local s = state[name]
    local d = s.d
    parts[#parts + 1] = string.format('%s: {"mobile": %s, "origin": %s, "logical_width": %d, "logical_height": %d, '
     .. '"scale": %.6g, "scale_120": %d, "applied_scale": %.6g, "policy_logical_width": %d, "policy_logical_height": %d, '
     .. '"explicit": %s, "auto_apply": %s, "source": %s, "dpi": %.1f, "glass_preset": %s}',
     jstr(name), tostring(s.mobile), jstr(s.origin), s.w, s.h,
     d.scale, d.scale_120, s.applied, d.logical_width, d.logical_height,
     tostring(d.explicit), tostring(d.auto_apply), jstr(d.source), tonumber(d.dpi) or 0, jstr(s.fx or ""))
   end
   local f = io.open(path .. ".new", "w")
   if not f then return end
   -- hyprbars_tabs: the plugin draws the mobile controls (hyprbars:mobile rule live); the shell then draws none
   f:write('{"version": 1, "hyprbars_tabs": ' .. tostring(tabs_live) .. ', "outputs": {' .. table.concat(parts, ", ") .. '}, "config": ' .. config_json .. '}\n')
   f:close()
   os.rename(path .. ".new", path)
  end
  local function reconcile(added)
   local state, list = {}, hl.get_monitors() or {}
   if type(list) ~= "table" then list = {} end
   if added ~= nil then list[#list + 1] = added end
   local hints = S and dpi_hints() or {}
   for i = 1, #list do
    local m = list[i]
    local okm, name, w, h = pcall(function() local lw, lh = logical(m) return m.name, lw, lh end)
    if okm and type(name) == "string" and name:match("^[%w_%-]+$") and not state[name] then
     local okd, d = pcall(decide, m, name, w, h, hints)
     if not okd then
      if io and io.stderr then io.stderr:write("MiOS: scale policy: " .. tostring(d) .. "\n") end
      d = {mobile = is_mobile(name, w, h), scale = tonumber(m.scale) or 1, scale_120 = 120, logical_width = w,
       logical_height = h, explicit = false, auto_apply = false, source = "error", dpi = 0}
     end
     local fx = FX and FX.applies[origin(name)] and FX.preset or nil
     state[name] = {mobile = d.mobile, origin = origin(name), w = w, h = h, applied = tonumber(m.scale) or 1, d = d, fx = fx}
     apply(name, d.mobile)
     apply_fx(name, fx ~= nil)
     pcall(schedule, m, name, d)
    end
   end
   for name in pairs(rules) do
    if not (state[name] and state[name].mobile) then apply(name, false) end
   end
   for name in pairs(fxrules) do
    if not (state[name] and state[name].fx) then apply_fx(name, false) end
   end
   publish(state)
  end
  local function guarded(fn)
   return function(...)
    local okc, e = pcall(fn, ...)
    if not okc and io and io.stderr then io.stderr:write("MiOS: mobile profile: " .. tostring(e) .. "\n") end
   end
  end
  hl.on("monitor.added", guarded(function(m) reconcile(m) end))
  hl.on("monitor.removed", guarded(function() reconcile() end))
  hl.on("monitor.layout_changed", guarded(function() reconcile() end))
  reconcile()
 end)
 if not ok and io and io.stderr then io.stderr:write("MiOS: Hyprland mobile section failed: " .. tostring(err) .. "\n") end
end
-- end MiOS mobile layout profile
